Translate("ruRU", "hillsbrad-foothills", {
	title = "Предгорья Хилсбрада",
	aliases = { "Хилсбрад" },
	sections = {
		{
			title = "Обзор",
			text = [=[Предгорья Хилсбрада — зеленые южные рубежи старого королевства {link:lordaeron}Лордерон{/link}. Они тянутся от снегов {link:alterac-mountains}Альтеракских гор{/link} до мягкого морского побережья. Чума, убившая Лордерон, обошла их стороной, и недолгое время казалось, что Хилсбрад уцелел. Это было не так. Сегодня предгорья — поле битвы. {link:humans}Люди{/link} Южнобережья держат побережье, {link:forsaken}Отрекшиеся{/link} держат Мельницу Таррен на севере, а между ними одна за другой горят фермы Хилсбрада.]=],
		},
		{
			title = "Истоки",
			text = [=[Ни одна летопись не говорит, когда в этих холмах поднялись первые деревни. Они были частью {link:lordaeron}Лордерон{/link}а столько, сколько стояло это королевство. На восточной границе стоит древняя стена, которая носит имя {link:thoradin}Торадин{/link}а, основателя {link:arathor}Аратора{/link}. Когда в {link:first-war}Первую войну{/link} пал {link:stormwind-city}Штормград{/link}, его беженцы сошли на берег в {link:southshore}Южнобережье{/link}, и Хилсбрад первым из северных земель встретил их.]=],
		},
		{
			title = "Наши дни",
			text = [=[Хилсбрад зажат между двумя войнами. {link:high-executor-darthalia}Верховный исполнитель Дарталия{/link} командует Отрекшимися Мельницы Таррен от имени {link:sylvanas-windrunner}Темной Госпожи{/link} и повелителя {link:varimathras}Вариматаса{/link}. Ее стражи смерти совершают набеги на фермы Хилсбрадских полей, а аптекари {link:royal-apothecary-society}Королевского общества аптекарей{/link} испытывают новые яды на фермерах и их животных. {link:southshore}Южнобережье{/link} и {link:dwarves}дворф{/link}ы {link:dun-garok}Дун Гарок{/link}а отвечают теми немногими солдатами, что у них есть. Тем временем {link:syndicate}Синдикат{/link} нападает на обе стороны из руин Крепости {link:durnholde-keep}Дарнхольд{/link}. Считают, что его убийцы уже расправились с одним мировым судьей Южнобережья и теперь охотятся на следующего. Недавно на Мельницу Таррен пришли {link:orcs}орк{/link}и, которых послал сам {link:thrall}Тралл{/link}, ибо Дарнхольд был когда-то тюрьмой вождя, и он хочет кое-что оттуда вернуть.]=],
		},
		{
			title = "Обитатели",
			text = [=[• {b}Жители Южнобережья.{/b} Рыбаки, солдаты и ученые, верные {link:alliance}Альянсу{/link}.
• {b}Фермеры Хилсбрада.{/b} Они по-прежнему работают на полях к западу от реки, на глазах у врага.
• {b}{link:forsaken}Отрекшиеся{/link}.{/b} Их стражи смерти, ловчие смерти и аптекари держат Мельницу Таррен.
• {b}{link:orcs}Орки{/link} Орды.{/b} Небольшой отряд, присланный из {link:durotar}Дуротара{/link}, и кузнец, который тихо трудится на Мельнице Таррен.
• {b}Дворфы {link:dun-garok}Дун Гарок{/link}а.{/b} Гарнизон {link:dwarves}дворфов{/link} на юго-востоке, давший клятву защищать людей и их рудник.
• {b}{link:syndicate}Синдикат{/link}.{/b} Воры и маги тени на службе у павших лордов {link:alterac-mountains}Альтерак{/link}а.
• {b}Звери и налетчики.{/b} {link:murlocs}Мурлоки{/link} на Западном побережье, {link:naga}наги{/link} на Восточном побережье, {link:gnolls}гноллы{/link} во Владении Нетандера и {link:ogres}огр{/link}ы, которые спускаются с Альтерака.]=],
		},
		{
			title = "История",
			text = [=[• {b}Беженцы.{/b} После падения {link:stormwind-city}Штормград{/link}а уцелевшие пересекли море и высадились в {link:southshore}Южнобережье{/link}. {link:ott}Отт{/link}уда весть об {link:orcs}орк{/link}ах понесли королю {link:terenas-menethil}Теренасу Менетилу{/link}.
• {b}Вторая война.{/b} {link:anduin-lothar}Андуин Лотар{/link} собрал армии {link:alliance}Альянс{/link}а в Хилсбраде. {link:horde}Орда{/link} высадилась близ Южнобережья, и здесь два войска сошлись в первой большой сухопутной битве {link:second-war}Второй войны{/link}. Здесь же рыцари смерти Орды впервые встретились с паладинами, которых вел {link:uther-the-lightbringer}Утер Светоносный{/link}.
• {b}Лагеря.{/b} После войны {link:durnholde-keep}Крепость Дарнхольд{/link} стала средоточием лагерей, где держали побежденных орков. В ее стенах рабом вырос молодой орк по имени {link:thrall}Тралл{/link}. Он бежал, вернулся во главе новой Орды и обратил крепость в руины.
• {b}Наши дни.{/b} {link:lordaeron}Лордерон{/link}а больше нет, и даже его южные холмы ускользают из рук людей.]=],
		},
		{
			title = "Предания предгорий",
			text = [=[• Жители Южнобережья говорят, что их повара — лучшие к северу от {link:stormwind-city}Штормград{/link}а. Путники приходили даже из Темнолесья ради миски черепахового супа, который варит повар Джессен.
• На кладбище Южнобережья п{link:ogres}огр{/link}ебен волшебник по имени {link:helcular}Хелькулар{/link}. Его убила толпа горожан прежде, чем он завершил свой темный ритуал. Кое-кто на Мельнице Таррен намерен его довершить.]=],
		},
	},
})

Translate("ruRU", "southshore", {
	title = "Южнобережье",
	sections = {
		{
			title = "Обзор",
			text = [=[Южнобережье — портовый город на южном побережье {link:hillsbrad-foothills}Хилсбрад{/link}а, выросший вокруг гавани, таверны и ратуши. Он был рыбацкой деревней, когда на его берег сошли беженцы из {link:stormwind-city}Штормград{/link}а. Он по-прежнему верен {link:alliance}Альянсу{/link} и теперь остался одним из последних людских городов севера. Правит им мировой судья Генри {link:magistrate-henry-maleb}Малеб{/link}, а стражей командует маршал {link:marshal-redpath}Редпат{/link}. {link:syndicate}Синдикат{/link} поклялся его погубить, а {link:forsaken}Отрекшиеся{/link} Мельницы Таррен открыто говорят, что Южнобережье сгорит следом за Хилсбрадом.]=],
		},
		{
			title = "Гавань",
			text = [=[С его холма взлетают грифоны. С недавних пор к его причалу стали приходить новые корабли, которые идут в {link:menethil-harbor}Гавань Менетилов{/link} и в {link:auberdine}Аубердин{/link} в далеком {link:kalimdor}Калимдор{/link}е. В городе поселился и посланник ордена {link:kirin-tor}Кирин-Тор{/link}.]=],
		},
	},
})

Translate("ruRU", "tarren-mill", {
	title = "Мельница Таррен",
	sections = {
		{
			title = "Обзор",
			text = [=[Мельница Таррен была людским городом {link:lordaeron}Лордерон{/link}а, стоявшим среди садов в холмах под {link:alterac-mountains}Альтерак{/link}ом. Его церковь и дома еще стоят, но сады засохли, а его жители — мертвецы. {link:forsaken}Отрекшиеся{/link} держат его как свой оплот на юге. Отсюда верховный исполнитель {link:high-executor-darthalia}Дарталия{/link} ведет войну против {link:hillsbrad-foothills}Хилсбрад{/link}а, а аптекари {link:royal-apothecary-society}Королевского общества аптекарей{/link} варят свою чуму. Летучие мыши носят всадников в {link:undercity}Подгород{/link}. В городе стоит лагерем и отряд {link:orcs}орк{/link}ов, которых послал {link:thrall}Тралл{/link}, ибо руины {link:durnholde-keep}Дарнхольд{/link}а лежат сразу за рекой.]=],
		},
	},
})

Translate("ruRU", "durnholde-keep", {
	title = "Крепость Дарнхольд",
	aliases = { "Дарнхольд" },
	sections = {
		{
			title = "Обзор",
			text = [=[Крепость Дарнхольд была некогда сильнейшей твердыней южного {link:lordaeron}Лордерон{/link}а. После Второй войны она стала средоточием лагерей, где держали побежденных {link:orcs}орк{/link}ов, и правил ею генерал-лейтенант {link:aedelas-blackmoore}Эделас Блэкмур{/link}. Здесь рабом вырос {link:thrall}Тралл{/link}, попавший сюда младенцем. Вернувшись вождем, он разрушил ее стены и похоронил ее лорда под камнями. Руины занял {link:syndicate}Синдикат{/link}. Там трудятся его маги тени, а его тюремщики держат в старых камерах пленных орков. Недавно от них сбежал орк по имени Горграш, и он ждет у стен.]=],
		},
	},
})

Translate("ruRU", "hillsbrad-fields", {
	title = "Хилсбрадские поля",
	sections = {
		{
			title = "Обзор",
			text = [=[Хилсбрадские поля — пахотные земли к западу от реки, и в их сердце стоит город {link:hillsbrad-foothills}Хилсбрад{/link}. Его мировой судья {link:magistrate-burnside}Бернсайд{/link} и городской совет хранят старую хартию города, «Хилсбрадскую прокламацию», и регистрационную книгу его жителей. В его кузнице хранится запас железа. Его фермы кормят все предгорья. Вот почему {link:forsaken}Отрекшиеся{/link} бьют сюда первым делом. Стражи смерти нападают на северные фермы, крестьяне бегут в южные сады, а город ждет удара, который ему не под силу отразить.]=],
		},
	},
})

Translate("ruRU", "azurelode-mine", {
	title = "Лазуритовый рудник",
	sections = {
		{
			title = "Обзор",
			text = [=[Лазуритовый рудник лежит в холмах к югу от {link:hillsbrad-foothills}Хилсбрад{/link}а, над Западным побережьем. Его железо питает кузни {link:alliance}Альянса{/link}. За работой рудокопов следит штейгер Бондс, а у входа стоят часовые. Альянс яростно его защищает. {link:forsaken}Отрекшиеся{/link} очень хотят его заполучить. Темной Госпоже нужно железо, чтобы вооружить своих солдат, и рудник, отнятый у людей, дал бы ей его. У рудокопов есть причина бояться. Имя их штейгера стоит в списке верховного исполнителя.]=],
		},
	},
})

Translate("ruRU", "dun-garok", {
	title = "Дун Гарок",
	sections = {
		{
			title = "Обзор",
			text = [=[Дун Гарок — крепость {link:dwarves}дворф{/link}ов на юго-востоке {link:hillsbrad-foothills}Хилсбрад{/link}а, построенная у Стены {link:thoradin}Торадин{/link}а. Ее гарнизон из горцев, стрелков и жрецов возглавляет капитан {link:captain-ironhill}Железный Холм{/link}. Дворфы пришли помочь людям предгорий и стоят на страже их земель. Они варят крепкий стаут и не прочь прибрать к рукам снаряжение беспечного лазутчика Отрекшихся, если найдут его. {link:tarren-mill}Мельница Таррен{/link} числит их среди злейших своих врагов. Ее приказ прост: Дун Гарок должен пасть.]=],
		},
	},
})

Translate("ruRU", "nethander-stead", {
	title = "Владение Нетандера",
	sections = {
		{
			title = "Обзор",
			text = [=[Владение Нетандера — заброшенная ферма к востоку от Южнобережья, за рекой. Ни одна запись не говорит, что стало с семьей Нетандеров. Теперь на ее полях живут {link:gnolls}гноллы{/link} племени Грязнорылов, а среди сорняков густо растут бледные грибы, которые называют цветами Грязнорылов. Эти цветы смердят, и именно за это их ценят аптекари Мельницы Таррен. Они — основа одного из самых смертоносных зелий Общества. {link:apothecary-lydon}Аптекарь Лайдон{/link} сказал, что грязные гноллы все-таки хоть на что-то годятся.]=],
		},
	},
})

Translate("ruRU", "purgation-isle", {
	title = "Остров Очищения",
	sections = {
		{
			title = "Обзор",
			text = [=[Остров Очищения — крутой остров у юго-западного побережья {link:hillsbrad-foothills}Хилсбрад{/link}а, увенчанный разрушенной башней и опоясанный старым кладбищем. Его мертвые не знают покоя. Осужденные клирики, монахи и послушники бродят среди могил рядом с проклятыми паладинами и судьями и корчащимися магами. Сила их велика и далеко превосходит силу зверей и налетчиков большой земли. Ни одна летопись не говорит, кем они были при жизни, какое преступление или рок приковали их к острову и почему среди них так много служителей {link:holy-light}Свет{/link}а.]=],
		},
	},
})

Translate("ruRU", "darrow-hill", {
	title = "Холм Дарроу",
	sections = {
		{
			title = "Обзор",
			text = [=[Холм Дарроу поднимается на севере {link:hillsbrad-foothills}Хилсбрад{/link}а, под высотами {link:alterac-mountains}Альтерак{/link}а. По его склонам бродят горные львы и олени, а в пещерах над ним обитают йети. Это дикий край, и ни одного города на нем нет. Именно в этих холмах волшебник {link:helcular}Хелькулар{/link} держал свое тайное логово, пока его не нашли горожане Южнобережья. С тех пор его пещеры заняли йети, а его ритуальные огни все еще горят во тьме. Логово было тайной, и ни одна запись не говорит, как горожане о нем узнали.]=],
		},
	},
})

Translate("ruRU", "eastern-strand", {
	title = "Восточное побережье",
	sections = {
		{
			title = "Обзор",
			text = [=[Восточное побережье — скалистый берег к востоку от Южнобережья, который тянется к {link:dun-garok}Дун Гарок{/link}у. {link:naga}Наги{/link} {link:kinelory}Кин{/link}жального Шипа вышли из моря и объявили его своим. Их сирены и береговые охотники рыщут по пляжу, и среди них охотится нага редкой силы, леди Зефрис. Офицеры Южнобережья боятся того, чего хотят наги, и весть о них дошла до верховного командования {link:alliance}Альянс{/link}а. Никто в {link:southshore}Южнобережье{/link} не может сказать, откуда пришли наги.]=],
		},
	},
})

Translate("ruRU", "western-strand", {
	title = "Западное побережье",
	sections = {
		{
			title = "Обзор",
			text = [=[Западное побережье — длинный берег к западу от Южнобережья, под Лазуритовым рудником. {link:murlocs}Мурлоки{/link} Рваного Плавника поставили вдоль него свои лагеря — так близко к городу, что это тревожит его стражу. {link:marshal-redpath}Маршал Редпат{/link} хочет, чтобы их отбросили, и требует их головы как доказательство. Его лейтенант охотнее пьет, чем идет в бой, и задача обычно достается чужакам. Лейтенант уже несколько недель не ел рыбы. Мурлока этого племени по имени Скаргил видят редко, но те, кто его встретил, редко его забывают.]=],
		},
	},
})

Translate("ruRU", "southpoint-tower", {
	title = "Южная башня",
	sections = {
		{
			title = "Обзор",
			text = [=[Южная башня — разрушенная сторожевая башня на дальнем западном краю {link:hillsbrad-foothills}Хилсбрад{/link}а, на дороге в {link:silverpine-forest}Серебряный бор{/link}. Когда-то она стерегла подступы к предгорьям. Теперь в ней прячется одна-единственная разведчица Отрекшихся. Из-за ее разбитых стен ловчий смерти {link:deathstalker-lesh}Леш{/link} следит за городом Хилсбрад и шлет вести на восток, на Мельницу Таррен. Она одна, далеко от всякой помощи, а вокруг — дороги {link:alliance}Альянс{/link}а. Ее последнее послание было коротким. В нем говорилось, что пришло время ударить.]=],
		},
	},
})

Translate("ruRU", "thoradin-s-wall", {
	title = "Стена Торадина",
	sections = {
		{
			title = "Обзор",
			text = [=[Стена Торадина — {link:ogres}огр{/link}омный разрушенный вал, который отделяет {link:hillsbrad-foothills}Предгорья Хилсбрада{/link} от {link:arathi-highlands}Нагорья Арати{/link}. Она носит имя {link:thoradin}Торадин{/link}а, первого короля {link:arathor}Аратора{/link}, и она старше любого из королевств, что стоят сегодня. Большинство говорит, что ее возвели, чтобы сдержать троллей Амани. Ее камни потрескались, а башен больше нет, но она по-прежнему отмечает границу. {link:dwarves}Дворфы{/link} {link:dun-garok}Дун Гарок{/link}а построили свою крепость в ее тени. Путникам, идущим в Нагорье Арати, все еще приходится ее пересекать.]=],
		},
	},
})

Translate("ruRU", "aedelas-blackmoore", {
	title = "Эделас Блэкмур",
	subtitle = "Хозяин Дарнхольда",
	allegiance = "Королевство Лордерон · Крепость Дарнхольд",
	aliases = { "Блэкмур" },
	sections = {
		{
			title = "Обзор",
			text = [=[Эделас Блэкмур был лордом Крепости {link:durnholde-keep}Дарнхольд{/link} и хозяином лагерей, где после {link:second-war}Второй войны{/link} держали побежденных {link:orcs}орк{/link}ов. Он был суровым бойцом, тяжелым пьяницей и человеком большого честолюбия. В глуши он нашел осиротевшего младенца-орка и вырастил его рабом. Этим орком был {link:thrall}Тралл{/link}. Блэкмур хотел сделать из него оружие. Вместо этого Тралл стал вождем, который освободил орков и убил его.]=],
		},
		{
			title = "Значение",
			text = [=[Блэкмур — человек, который создал вождя, каким стал {link:thrall}Тралл{/link}, во всех смыслах, каких сам не желал. Его жестокость показала молодому {link:orcs}орк{/link}у, какими могут быть люди. Доброта других в его же доме показала, что люди могут быть и иными. Без этого человека не было бы вождя, а без вождя не было бы новой {link:horde}Орды{/link}.]=],
		},
		{
			title = "Сын изменника",
			text = [=[Блэкмур хорошо сражался во Вторую войну и славился яростью к {link:orcs}орк{/link}ам. Но имя его было тяжким бременем. Его отца осудили за измену, и шепот преследовал сына всю жизнь. Он пил, чтобы выйти на бой, и стал пить больше, когда война кончилась. Когда ему отдали {link:durnholde-keep}Дарнхольд{/link} и лагеря, его власть выросла, а с ней и его пороки.]=],
		},
		{
			title = "Орчонок",
			text = [=[На охоте со своим слугой Таммисом Фокстоном он нашел младенца-{link:orcs}орк{/link}а среди тел его убитых родителей. Блэкмур отнес ребенка в {link:durnholde-keep}Дарнхольд{/link} и дал ему имя {link:thrall}Тралл{/link}. Он велел научить мальчика читать, писать и сражаться и выставлял его на арене против бойцов других лордов. Втайне он мечтал о большем. Однажды Тралл поведет армию орков из лагерей, и через него Блэкмур будет править. С мальчиком он часто был жесток, а иногда добр, и никогда не видел этой разницы так, как видел ее Тралл.]=],
		},
		{
			title = "Падение Дарнхольда",
			text = [=[{link:thrall}Тралл{/link} бежал с помощью дочери слуги, девушки по имени {link:taretha-foxton}Тарета Фокстон{/link}, которую Блэкмур против ее воли сделал своей любовницей. Годы спустя {link:orcs}орк{/link} вернулся во главе свободной Орды и разбил лагеря один за другим. В ночь перед осадой Блэкмур узнал, что Тарета тайно виделась с беглецом. Он велел предать ее смерти. Когда Тралл пришел на переговоры к воротам, пьяный Блэкмур сбросил ее голову со стен. Орки взяли крепость приступом. Тралл нашел его внутри и убил в поединке. Потом он воззвал к духу земли, и {link:durnholde-keep}Дарнхольд{/link} рухнул на тело своего хозяина.]=],
		},
	},
	chapters = {
		{
			title = "Наследие лорда Блэкмура",
			hint = "Узнайте, что лорд Синдиката замышляет против орков.",
			text = [=[Его честолюбивые замыслы не умерли вместе с ним. Орк {link:gol-dir}Гол'дир{/link}, попавший в плен к {link:syndicate}Синдикату{/link}, узнал, что лорд Синдиката, {link:lord-aliden-perenolde}Алиден Перенольд{/link}, называл его своим наставником. Перенольд собирался обратить в рабов {link:orcs}орк{/link}ов, которые встанут против него, как до него задумывали его отец и его учитель.]=],
		},
	},
	mentions = {
		{ text = "Наследие лорда Блэкмура" },
		{ text = "{link:lord-aliden-perenolde}Лорд Алиден Перенольд{/link}" },
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "его раб и его убийца" },
		{ id = "taretha-foxton", name = "Тарета Фокстон", note = "его любовница, убитая по его приказу" },
		{ id = "aliden-perenolde", name = "Алиден Перенольд", note = "его ученик" },
		{ id = "durnholde-keep", name = "Крепость Дарнхольд", note = "его твердыня и его могила" },
	},
})

Translate("ruRU", "taretha-foxton", {
	title = "Тарета Фокстон",
	subtitle = "Подруга вождя",
	allegiance = "Крепость Дарнхольд",
	aliases = { "Тарета", "Тари" },
	sections = {
		{
			title = "Обзор",
			text = [=[Тарета Фокстон была девушкой из Крепости {link:durnholde-keep}Дарнхольд{/link}, дочерью слуги Таммиса Фокстона, который служил лорду. Ближе нее у молодого {link:orcs}орк{/link}а {link:thrall}Тралл{/link}а не было никого, кто походил бы на семью. Она тайно писала ему, когда он был рабом, помогла ему бежать и заплатила за его свободу жизнью.]=],
		},
		{
			title = "Значение",
			text = [=[От лорда {link:aedelas-blackmoore}Блэкмур{/link}а {link:thrall}Тралл{/link} узнал, что такое жестокость. От нее он узнал, что люди могут быть добрыми. Память о ней — одна из причин, по которым вождь {link:horde}Орды{/link} никогда не питал ненависти ко всему человечеству.]=],
		},
		{
			title = "Деяния",
			text = [=[• Ребенком она заметила, что младенец-{link:orcs}орк{/link} не может есть мясо, которое ему дают, и тем спасла ему жизнь. Его выкормила ее мать.
• Она прятала записки в книгах, которые носила в камеру орка, и они переписывались годами.
• Когда {link:thrall}Тралл{/link} бежал из {link:durnholde-keep}Дарнхольд{/link}а, она устроила пожар, чтобы отвлечь стражу, и оставила ему плащ, чтобы пройти ворота. Идти с ним она отказалась, боясь того, что {link:aedelas-blackmoore}Блэкмур{/link} сделает с ее семьей.
• Она тайно встретилась с ним в ночь перед тем, как его армия подошла к Дарнхольду. Блэкмур велел следить за ней, и он же велел ее убить.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна запись не говорит, как ее подвеска попала в руки лордов {link:alterac-mountains}Альтерак{/link}а и где покоится сама Тарета.]=],
		},
	},
	chapters = {
		{
			title = "Дар Тареты",
			hint = "Верните подвеску, которую желает получить вождь.",
			text = [=[Спустя много лет после ее смерти {link:orcs}орк{/link}и, которых послал {link:thrall}Тралл{/link}, пришли в {link:hillsbrad-foothills}Хилсбрад{/link} за одной-единственной подвеской, которая некогда принадлежала ей. Они нашли ее на шее женщины по имени {link:elysa}Элиза{/link}, любовницы лорда {link:lord-aliden-perenolde}Алидена Перенольда{/link}. Та отдала ее с радостью. Орк, который принял подвеску, не мог понять, зачем вождю тратить так много ради такой малой вещи.]=],
		},
	},
	mentions = {
		{ text = "Наследие лорда {link:aedelas-blackmoore}Блэкмур{/link}а" },
		{ text = "{link:lord-aliden-perenolde}Лорд Алиден Перенольд{/link}" },
		{ text = "{link:dar}Дар{/link} Тареты" },
	},
	bonds = {
		{ id = "thrall", name = "Тралл", note = "ее друг, которого она звала братом" },
		{ id = "aedelas-blackmoore", name = "Эделас Блэкмур", note = "ее хозяин и ее убийца" },
		{ id = "krusk", name = "Круск", note = "вернул ее подвеску вождю" },
	},
})

Translate("ruRU", "loremaster-dibbs", {
	title = "Хранитель знаний Диббс",
