			text = [=[Хранитель знаний Диббс — ученый Южнобережья, старый книжник, который живет ближе к руинам {link:alterac-mountains}Альтерак{/link}а, чем любой другой ученый муж {link:alliance}Альянс{/link}а. Он скорбит о библиотеках этого павшего королевства. Когда с гор приносят странное письмо или обрывок заколдованного пергамента, его несут к нему.]=],
		},
		{
			title = "Значение",
			text = [=[Диббс — память Южнобережья и его толкователь загадок. Через его руки проходят потерянные книги {link:alterac-mountains}Альтерак{/link}а и тайные письма {link:syndicate}Синдиката{/link}. Он знает пределы собственной учености и знает, кого спросить за этими пределами.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он направляет поиски книг, которые {link:ogres}огр{/link}ы растащили из {link:ruins-of-alterac}Руин Альтерака{/link}.
• Он ищет «Руку Гри'лека» — книгу древних преданий троллей, последний известный целый список которой хранился в руинах.
• Найденные книги он отправляет в {link:stormwind-city}Штормград{/link}, где их принимает {link:milton-sheaf}Милтон Шиф{/link}, для {link:royal-library}Королевской библиотеки{/link}.
• Шифрованные письма {link:syndicate}Синдикат{/link}а он отправляет в {link:ironforge}Стальгорн{/link}, где их читает {link:prospector-stormpike}геолог Штормпайк{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Книги Альтерака",
			hint = "Верните хранителю знаний тома Альтерака.",
			text = [=[До своего падения {link:alterac-mountains}Альтерак{/link} владел большой библиотекой. Теперь среди его руин живут {link:crushridge-ogres}огры Раздробленного Хребта{/link}, и книги им ни к чему — разве что жечь или топтать. Диббс слишком стар для подъема в горы. Поэтому вместо него идут другие и приносят то, что {link:ogres}огр{/link}ы еще не успели уничтожить. Книгу «Рука Гри'лека» он оставляет себе для изучения, а остальные отсылает в {link:stormwind-city}Штормград{/link}.]=],
		},
		{
			title = "Шифрованное письмо",
			hint = "Принесите хранителю знаний шифр, найденный у Синдиката.",
			text = [=[Письмо, найденное у воров {link:syndicate}Синдикат{/link}а, было написано шифром, какого Диббс никогда не видел. Он так и признал и переслал письмо своему другу в {link:ironforge}Стальгорн{/link}. Когда его наконец прочли, в нем говорилось о силе, которая стоит за Синдикатом и не имеет ничего общего со знатью {link:alterac-mountains}Альтерак{/link}а.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:southshore}Южнобережье{/link}: посылает {link:milton-sheaf}Милтон Шиф{/link}]=],
		},
		{ text = "Сохранение знаний" },
		{ text = "Возвращение к библиотекарю" },
		{ text = "Шифрованное письмо" },
		{ text = "Письмо геологу Штормпайку" },
		{ text = "Заколдованный пергамент" },
		{ text = "Расшифровка геолога Штормпайка" },
	},
	bonds = {
		{ id = "milton-sheaf", name = "Милтон Шиф", note = "библиотекарь Штормграда" },
		{ id = "prospector-stormpike", name = "геолог Штормпайк", note = "читает его шифры" },
		{ id = "magistrate-henry-maleb", name = "мировой судья Генри Малеб", note = "получает то, что открывают письма" },
	},
})

