Translate("ruRU", "raleigh-the-devout", {
	title = "Рэлей Благочестивый",
	subtitle = "Рыцарь ордена, который отвернулся",
	found = "Верхний этаж таверны Южнобережья",
	hint = [=[Найдите бывшего рыцаря Алого ордена, который не покидает верхнего этажа таверны Южнобережья.]=],
	allegiance = "Свет",
	aliases = { "Рэлей" },
	sections = {
		{
			title = "Обзор",
			text = [=[Рэлей Благочестивый некогда с гордостью служил {link:scarlet-crusade}Алому ордену{/link}. Он верил в его дело — избавить мир от нежити. В монастыре ордена он увидел, как пытают невинных людей, которых обвинили в чуме лишь за то, что на них не было его накидки. Он ушел и теперь тихо живет в {link:southshore}Южнобережье{/link}.]=],
		},
		{
			title = "Значение",
			text = [=[Кое-кто в ордене все еще верит, что Рэлей на их стороне. Те, кого к нему посылают, узнают вместо этого правду об ордене.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он призывает предать смерти предводителей {link:scarlet-monastery}Монастыря Алого ордена{/link} во имя {link:holy-light}Света{/link}, чтобы истинное дело однажды могло возродиться.]=],
		},
	},
	mentions = {
		{ text = "По алому пути" },
		{ text = "Во имя {link:holy-light}Свет{/link}а" },
	},
	bonds = {
		{ id = "scarlet-crusade", name = "Алый орден", note = "орден, который он покинул" },
	},
})

Translate("ruRU", "innkeeper-anderson", {
	title = "Трактирщик Андерсон",
	subtitle = "Трактирщик Южнобережья",
	found = "Таверна Южнобережья",
	hint = "Поговорите с трактирщиком Южнобережья.",
	allegiance = "Южнобережье",
	aliases = { "Андерсон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Андерсон держит таверну Южнобережья — самый людный дом в городе. Под его крышей собираются солдаты после службы, горожане, бывший рыцарь Алого ордена и {link:dwarves}дворф{/link}, который редко бывает трезв. Усталые путники с грифоньего холма и из гавани находят у него постель и еду.]=],
		},
		{
			title = "Значение",
			text = [=[Таверна — место, где {link:southshore}Южнобережье{/link} разговаривает. Под одной крышей лейтенант жалуется на свое назначение, бывший рыцарь ордена не выходит из комнаты наверху, а {link:dwarves}дворф{/link}-хмелевар ждет в п{link:ogres}огр{/link}ебе самогон от должника.]=],
		},
		{
			title = "Неизвестное",
			text = [=[О нем самом записано мало. Ни одна запись не называет его имени и не говорит, как давно он держит таверну.]=],
		},
	},
	bonds = {
		{ id = "brewmeister-bilger", name = "хмелевар Билгер", note = "пьет в его погребе" },
		{ id = "lieutenant-farren-orinelle", name = "лейтенант Фаррен Оринелл", note = "пьет за его столами" },
	},
})

Translate("ruRU", "brewmeister-bilger", {
	title = "Хмелевар Билгер",
	subtitle = "Хмелевар Южнобережья",
	found = "Погреб таверны Южнобережья",
	hint = [=[Загляните в погреб таверны Южнобережья и найдите дворфа-хмелевара.]=],
	allegiance = "Южнобережье",
	aliases = { "Билгер" },
	sections = {
		{
			title = "Обзор",
			text = [=[Билгер — {link:dwarves}дворф{/link}, который не покидает п{link:ogres}огр{/link}еба таверны Южнобережья. Он варит и пьет, а между тем и другим икает. Один дворф из Болотины задолжал ему, и Билгер рассчитывает получить долг самогоном.]=],
		},
		{
			title = "Значение",
			text = [=[Его торговля простирается далеко за пределы Южнобережья. Его должники живут даже в Болотине, за морем на юге.]=],
		},
		{
			title = "Деяния",
			text = [=[• Партию самогона ему задолжал {link:foggy-mackreel}Фогги Маккрил{/link}, {link:dwarves}дворф{/link} из Болотины, который часто запаздывает с оплатой счетов.
• Он считает, что ничто не с{link:ogres}огр{/link}еет дворфа в свежий день лучше, чем самогон этого должника.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Ни одна запись не говорит, как Билгер попал в {link:southshore}Южнобережье{/link}.]=],
		},
	},
	mentions = {
		{
			text = [=[Самогон {link:dwarves}дворф{/link}а {link:foggy-mackreel}Маккрил{/link}а]=],
		},
	},
	bonds = {
		{ id = "innkeeper-anderson", name = "трактирщик Андерсон", note = "держит таверну над его погребом" },
	},
})

Translate("ruRU", "phin-odelic", {
	title = "Фин Оделик",
	subtitle = "Искатель новой чумы",
	found = "Таверна Южнобережья",
	hint = [=[Поговорите с человеком в Южнобережье, который возглавляет отряд дознавателей.]=],
	allegiance = "Южнобережье · Альянс",
	aliases = { "Фин" },
	sections = {
		{
			title = "Обзор",
			text = [=[Фин Оделик возглавляет небольшой отряд искателей приключений, которые расследуют странные происшествия в предгорьях. Его двоюродному брату в {link:hillsbrad-foothills}Хилсбрад{/link}е пришлось убить своего пса по кличке Стэнли, после того как зверь раздулся до чудовищных размеров и стал бросаться на каждого, кто к нему подходил. Фин считает, что за этим стоит нежить.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он посылает за своими спутниками, которых зовут {link:quae}Квей{/link} и {link:kinelory}Кинелори{/link}: они ушли на Ферму Го'Шека в {link:arathi-highlands}Нагорье Арати{/link} и не дали о себе знать.
• Он собирает доказательства того, что {link:forsaken}Отрекшиеся{/link} работают над новой чумой.]=],
		},
	},
	chapters = {
		{
			title = "Признаки новой чумы",
			hint = "Найдите пропавших спутников дознавателя в Нагорье Арати.",
			text = [=[{link:quae}Квей{/link} и {link:kinelory}Кинелори{/link} были живы. Они шпионили за {link:orcs}орк{/link}ами Фермы Го'Шека, где скрывалось больше, чем видно глазу, и от Кинелори он получил вещи, взятые оттуда. С их помощью Фин надеялся наконец узнать, чем заняты {link:forsaken}Отрекшиеся{/link}.]=],
		},
	},
	mentions = {
		{ text = "Признаки новой чумы?" },
		{ text = "Признаки новой чумы?" },
	},
	bonds = {
		{ id = "stanley", name = "Стэнли", note = "пес его двоюродного брата" },
		{ id = "farmer-ray", name = "фермер Рэй", note = "хозяин пса" },
		{ id = "apothecary-lydon", name = "аптекарь Лайдон", note = "создатель яда, который он ищет" },
	},
})

Translate("ruRU", "tom-half-fish-wilson", {
	title = "Том \"Полурыба\" Уилсон",
	subtitle = "Старый моряк Южнобережья",
	found = "Причалы Южнобережья",
	hint = "Найдите старого моряка на причалах Южнобережья.",
	allegiance = "Южнобережье",
	aliases = { "Полурыба" },
	sections = {
		{
			title = "Обзор",
			text = [=[Том Уилсон, которого все зовут Полурыбой, живет у причалов Южнобережья. Он затаил обиду на человека из {link:menethil-harbor}Гавани Менетилов{/link} по имени {link:bart-tidewater}Барт Приливная Волна{/link}, который называет себя капитаном корабля «Девичья добродетель». Том говорит, что Барт вовсе не капитан, а всего лишь актер, выигравший свой корабль в карты, и что он жульничает.]=],
		},
		{
			title = "Значение",
			text = [=[Полурыба знает новые корабли, которые заходят в {link:southshore}Южнобережье{/link}, и знает, какой из них идет в {link:menethil-harbor}Гавань Менетилов{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он посылает подарок в {link:menethil-harbor}Гавань Менетилов{/link}, который следует вручить вместе с его почтением; получатель — {link:bart-tidewater}Барт Приливная Волна{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Недостаток добродетели",
			hint = "Доставьте подарок старого моряка в Гавань Менетилов.",
			text = [=[{link:bart-tidewater}Барт Приливная Волна{/link} развернул подарок и едва не лопнул от злости. По его словам, в карты жульничал как раз Том, и за это его выгнали из их круга. На золото, которое Барт выиграл после, и был куплен корабль «Девичья добродетель». Потом он вспомнил о хороших манерах и приветствовал посланца в Гавани Менетилов.]=],
		},
	},
	mentions = {
		{ text = "Недостаток добродетели" },
	},
})

Translate("ruRU", "high-executor-darthalia", {
	title = "Верховный исполнитель Дарталия",
	subtitle = "Верховный исполнитель Мельницы Таррен",
	found = "Мельница Таррен",
	hint = [=[Явитесь к верховному исполнителю, который командует Мельницей Таррен.]=],
	allegiance = "Отрекшиеся · стражи смерти",
	aliases = { "Дарталия" },
	sections = {
		{
			title = "Обзор",
			text = [=[Верховный исполнитель Дарталия командует {link:forsaken}Отрекшимися{/link} Мельницы Таррен и подчиняется прямо Темной Госпоже и ее наместнику {link:varimathras}Вариматасу{/link}. Ее задача — сломить людей {link:hillsbrad-foothills}Хилсбрад{/link}а, пока аптекари доделывают свою новую чуму. Она холодна, точна и скора на угрозы тем, кто мешкает.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она приказывает совершать набеги на фермы, кузницу, совет и рудник {link:hillsbrad-foothills}Хилсбрад{/link}а и осадить {link:dun-garok}Дун Гарок{/link}.
• Она назначает награды за воров {link:syndicate}Синдикат{/link}а и за людей, которых разыскивают за убийство Отрекшихся.
• О тех, кто хорошо ей служит, она шлет похвальный отзыв повелителю {link:varimathras}Вариматас{/link}у.]=],
		},
	},
	chapters = {
		{
			title = "Крик ворона",
			hint = "Отнесите послание разведчицы на Мельницу Таррен.",
			text = [=[Ее разведчица в Южной башне прислала одну-единственную фразу: «Крик ворона с запада зовет». Это значило, что {link:hillsbrad-foothills}Хилсбрад{/link} готов к удару. Дарталия начала наступление немедля.]=],
		},
	},
	mentions = {
		{ text = "Время нанести удар" },
		{ text = "{link:battle-of-hillsbrad}Битва за Хилсбрад{/link}" },
		{
			text = [=[{link:battle-of-hillsbrad}Битва за Хилсбрад{/link}: осада {link:dun-garok}Дун Гарок{/link}а]=],
		},
		{
			text = [=[{link:battle-of-hillsbrad}Битва за Хилсбрад{/link}: повелителю {link:varimathras}Вариматас{/link}у]=],
		},
		{ text = "РАЗЫСКИВАЮТСЯ: люди {link:syndicate}Синдикат{/link}а" },
		{ text = "РАЗЫСКИВАЕТСЯ: барон {link:baron-vardus}Вардус{/link}" },
		{ text = "Опасны!" },
	},
	bonds = {
		{ id = "varimathras", name = "Вариматас", note = "ее командир" },
		{ id = "deathstalker-lesh", name = "ловчий смерти Леш", note = "ее разведчица" },
		{ id = "captain-ironhill", name = "капитан Железный Холм", note = "ее враг в Дун Гароке" },
	},
})

Translate("ruRU", "deathstalker-lesh", {
	title = "Ловчий смерти Леш",
	subtitle = "Разведчица Южной башни",
	found = "Южная башня",
	hint = [=[Найдите разведчицу Отрекшихся, которая прячется в разрушенной башне на западном краю Хилсбрада.]=],
	allegiance = "Отрекшиеся · ловчие смерти",
	aliases = { "Леш" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ловчий смерти Леш несет одинокий дозор в руинах Южной башни, на западном краю предгорий. Ее задание — разведка. Она следит за городом {link:hillsbrad-foothills}Хилсбрад{/link} и ждет часа, когда он будет слабее всего.]=],
		},
		{
			title = "Значение",
			text = [=[{link:battle-of-hillsbrad}Битва за Хилсбрад{/link} началась с ее слова. Она отправила на Мельницу Таррен шифрованное послание. Для верховного исполнителя оно значило, что {link:hillsbrad-foothills}Хилсбрад{/link} созрел для нападения, и {link:high-executor-darthalia}Дарталия{/link} спустила своих стражей смерти на фермы.]=],
		},
		{
			title = "Деяния",
			text = [=[• Она ведет разведку города {link:hillsbrad-foothills}Хилсбрад{/link} для Отрекшихся — одна и далеко от Мельницы Таррен.
• Она подает сигнал, с которого начинается наступление.]=],
		},
	},
	mentions = {
		{ text = "Время нанести удар" },
	},
	bonds = {
		{ id = "high-executor-darthalia", name = "верховный исполнитель Дарталия", note = "получает ее послание" },
	},
})

Translate("ruRU", "apothecary-lydon", {
	title = "Аптекарь Лайдон",
	subtitle = "Аптекарь Мельницы Таррен",
	found = "Мельница Таррен",
	hint = "Найдите на Мельнице Таррен угрюмого аптекаря Общества.",
	allegiance = "Королевское общество аптекарей · Отрекшиеся",
	aliases = { "Лайдон" },
	sections = {
		{
			title = "Обзор",
			text = [=[Аптекарь Лайдон — человек {link:royal-apothecary-society}Королевского общества аптекарей{/link} на Мельнице Таррен. Это угрюмая душа, для которой каждый день нежизни — мука. Лишь одно поднимает ему настроение: страдания живых. Его работа — подготовить новую чуму Темной Госпожи для {link:hillsbrad-foothills}Хилсбрад{/link}а, и он делает ее тщательно и с жутким весельем.]=],
		},
		{
			title = "Значение",
			text = [=[{link:master-apothecary-faranell}Главный аптекарь Фаранелл{/link} называет его одним из самых преданных и искусных членов Общества. Именно в его эликсирах чуму, предназначенную для {link:scourge}Плети{/link}, впервые обращают против людей.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он варит три эликсира — страдания, боли и агонии, и каждый смертоноснее предыдущего.
• Он испытывает их на своей лягушке по кличке Умпи, на псе фермера Рэя и на пленных фермерах.
• Он варит для аптекаря {link:apothecary-zamah}Замы{/link} яд против {link:venture-company}Торговой Компании{/link} в Когтистых горах — из крови невинных, отнятой у магов {link:syndicate}Синдикат{/link}а.
• Он изучает яд паучьего бога троллей племени Сухокожих и отправляет его главному аптекарю.
• В скучные дни он открывает свою банку с формальдегидом, чтобы насладиться его ароматом, отчего Умпи беспокоится.]=],
		},
	},
	chapters = {
		{
			title = "Эликсир боли",
			hint = "Испытайте эликсир аптекаря на фермерском псе.",
			text = [=[Аптекарю нужно было испытание. Он послал свой эликсир на северную ферму {link:hillsbrad-foothills}Хилсбрад{/link}ских полей, чтобы его дали как лакомство маленькому псу по кличке Стэнли, принадлежавшему фермеру. То, во что пес превратился после, хозяину пришлось убить своими руками.]=],
		},
		{
			title = "Эликсир агонии",
			hint = "Отнесите чумное варево аптекаря пленным фермерам.",
			text = [=[Для последнего эликсира потребовались зловонные цветы из Владения Нетандера, коллоид, который приготовил собственной рукой {link:master-apothecary-faranell}Фаранелл{/link}, и бочонок {link:dwarves}дворф{/link}ийского стаута из {link:dun-garok}Дун Гарок{/link}а. Затем Лайдон велел оставить отравленный бочонок в комнате, где {link:forsaken}Отрекшиеся{/link} держали пленных фермеров. Он назвал это «устроить им праздник».]=],
		},
	},
	mentions = {
		{
			text = [=[Путь в {link:hillsbrad-foothills}Предгорья Хилсбрада{/link}: посылает аптекарь {link:apothecary-renferrel}Ренферрел{/link}]=],
		},
		{ text = "Эликсир страдания" },
		{ text = "Эликсир боли" },
		{ text = "Эликсир агонии" },
		{ text = "Эликсир агонии" },
		{ text = "Путь на Мельницу Таррен" },
		{ text = "Кровь невинных" },
		{ text = "Яд — в {link:undercity}Подгород{/link}" },
	},
	bonds = {
		{ id = "master-apothecary-faranell", name = "главный аптекарь Фаранелл", note = "его начальник" },
		{ id = "apothecary-renferrel", name = "аптекарь Ренферрел", note = "делится своими открытиями" },
		{ id = "apothecary-zamah", name = "аптекарь Зама", note = "просит у него яд" },
		{ id = "stanley", name = "Стэнли", note = "его подопытный" },
		{ id = "serge-hinott", name = "Серж Хинотт", note = "трудится рядом с ним" },
	},
})

Translate("ruRU", "serge-hinott", {
	title = "Серж Хинотт",
	subtitle = "Опытный алхимик Мельницы Таррен",
	found = "Мельница Таррен, рядом с аптекарем Лайдоном",
	hint = [=[Найдите на Мельнице Таррен алхимика, который терпеть не может, когда его отрывают от дела.]=],
