	mentions = {
		{ text = "{link:battle-of-hillsbrad}Битва за Хилсбрад{/link}" },
	},
	bonds = {
		{ id = "high-executor-darthalia", name = "верховный исполнитель Дарталия", note = "приказала его убить" },
