Translate("ruRU", "battle-of-hillsbrad", {
	title = "Битва за Хилсбрад",
	sections = {
		{
			title = "Обзор",
			text = [=[Битва за Хилсбрад — война, которую {link:forsaken}Отрекшиеся{/link} Мельницы Таррен ведут ныне против людей предгорий. Цель ее проста: сокрушать людей {link:hillsbrad-foothills}Хилсбрад{/link}а, пока аптекари не доделают новую чуму, а затем сровнять с землей {link:southshore}Южнобережье{/link}.]=],
		},
		{
			title = "Поход",
			text = [=[Приказ пришел верховному исполнителю от повелителя {link:varimathras}Вариматаса{/link}. Когда ее разведчица в Южной башне прислала весть, что город созрел, наступление началось по ступеням.

• {b}Фермы.{/b} Сначала стражи смерти ударили по северным фермам и их владельцам, чтобы лишить {link:hillsbrad-foothills}Хилсбрад{/link} пищи.
• {b}Сады.{/b} Крестьян, бежавших в южные сады, выследили там.
• {b}Кузница.{/b} Кузнеца и его подмастерьев убили, а городское железо унесли.
• {b}{link:shadow-council}Совет{/link}.{/b} Мирового судью и совет обрекли на смерть, хартию города — на сожжение, а регистрационную книгу — на кражу.
• {b}Рудник.{/b} На штейгера и рудокопов Лазуритового рудника напали, чтобы {link:sylvanas-windrunner}Темная Госпожа{/link} могла вооружать своих солдат из его запасов.
• {b}{link:dun-garok}Дун Гарок{/link}.{/b} Последней пришла осада крепости {link:dwarves}дворф{/link}ов у Стены {link:thoradin}Торадин{/link}а.]=],
		},
		{
			title = "Другая сторона",
			text = [=[{link:humans}Люди{/link} не умирают тихо. Горожане {link:hillsbrad-foothills}Хилсбрад{/link}а убивали стражников Отрекшихся, аптекарей и ловчих смерти и устраивали засады на обозы с припасами из {link:undercity}Подгород{/link}а. {link:high-executor-darthalia}Дарталия{/link} держит их имена в списке тех, за чью голову назначена награда.]=],
		},
		{
			title = "Аптекари",
			text = [=[Пока солдаты сражаются, аптекарь {link:apothecary-lydon}Лайдон{/link} испытывает свои эликсиры на собаках и пленных фермерах {link:hillsbrad-foothills}Хилсбрад{/link}а. Каждый из них задуман как шаг к чуме, которую повелела создать {link:sylvanas-windrunner}Темная Госпожа{/link}.]=],
		},
	},
})

Translate("ruRU", "internment-camps", {
	title = "Лагеря для интернированных",
	aliases = { "лагерь для интернированных" },
	sections = {
		{
			title = "Обзор",
			text = [=[После {link:second-war}Второй войны{/link} уцелевших {link:orcs}орк{/link}ов не предали мечу. Их собрали в лагеря для интернированных по всему {link:lordaeron}Лордерону{/link}, под охраной солдат {link:alliance}Альянс{/link}а. Лагеря задумывались как место, где держат побежденного врага. Они стали чем-то худшим.]=],
		},
		{
			title = "Оцепенение",
			text = [=[Отрезанные от демонической силы, которая прежде гнала их вперед, {link:orcs}орк{/link}и в лагерях стали вялыми и больными духом. Многие просто сидели за стенами и не пытались уйти. {link:humans}Люди{/link}, которые их стерегли, не могли этого понять. Одни жалели их. Другие на них наживались.]=],
		},
		{
			title = "Дарнхольд",
			text = [=[Лагерями управляли из Крепости {link:durnholde-keep}Дарнхольд{/link} в {link:hillsbrad-foothills}Хилсбраде{/link}, и начальствовал над ними генерал-лейтенант {link:aedelas-blackmoore}Эделас Блэкмур{/link}. За своими стенами он видел не только узников. Он видел армию, которая могла бы стать его армией, если бы ее повел {link:orcs}орк{/link}, которого он вырастил сам.]=],
		},
		{
			title = "Освобождение",
			text = [=[Этим {link:orcs}орк{/link}ом был {link:thrall}Тралл{/link}. Он бежал из {link:durnholde-keep}Дарнхольд{/link}а, нашел свободные кланы и постиг пути шаманов. Рядом с ним встал {link:orgrim-doomhammer}Оргрим Молот Рока{/link}, и вместе они ударяли по лагерям, одному за другим, и освобождали орков. Молот Рока пал в одной из этих битв. {link:nak}Нак{/link}онец Тралл пришел к самому Дарнхольду, и лагерям настал конец.]=],
		},
	},
})
